DROP TABLE IF EXISTS `opds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `opds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nmskpd` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dinas_id` bigint unsigned DEFAULT NULL,
  `unit_id` bigint unsigned DEFAULT NULL,
  `kode_sub_unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_sub_unit` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_pagu` decimal(18,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `source_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_identifier` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `opds_kode_unique` (`kode`),
  KEY `opds_dinas_id_foreign` (`dinas_id`),
  KEY `opds_unit_id_foreign` (`unit_id`),
  CONSTRAINT `opds_dinas_id_foreign` FOREIGN KEY (`dinas_id`) REFERENCES `dinas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `opds_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE SET NULL
